def atom_fraction(answer, atoms):
    value = normalize_answer(answer)
    if not isinstance(atoms,(list,tuple)) or len(atoms)>16:
        raise ValueError('bounded atom list required')
    normalized = [normalize_answer(a) for a in atoms]
    if any(not atom for atom in normalized):
        raise ValueError('nonempty atom required')
    return sum(atom in value for atom in normalized)/len(normalized) if normalized else None

def ranking_stats(ranked, gold, k):
    if type(k) is not int or not 1<=k<=64:
        raise ValueError('invalid cutoff')
    if not isinstance(ranked,(list,tuple)) or not isinstance(gold,(set,frozenset)) or len(ranked)>64 or len(gold)>64:
        raise ValueError('bounded ID collections required')
    if any(not isinstance(v,str) or not v.strip() for v in (*ranked,*gold)) or len(set(ranked))!=len(ranked):
        raise ValueError('unique nonblank ranking IDs required')
    top=ranked[:k]
    hits=len(set(top)&gold)
    rr=next((1/r for r,key in enumerate(top,1) if key in gold),0.0)
    return dict(precision=hits/k,recall=hits/len(gold) if gold else None,reciprocal_rank=rr if gold else None)

