def dcg_at_k(grades, k):
    if type(k) is not int or not 1<=k<=64 or not isinstance(grades,(list,tuple)) or len(grades)>64:
        raise ValueError('invalid DCG input')
    if any(type(g) is not int or not 0<=g<=3 for g in grades):
        raise ValueError('reviewed integer grade required')
    return sum(((2**g-1)/log2(r+1) for r,g in enumerate(grades[:k],1)),0.0)

