def graded_ndcg(ranked, grades, k):
    if not isinstance(ranked,(list,tuple)) or not isinstance(grades,dict) or len(ranked)>64 or len(grades)>64:
        raise ValueError('invalid ranking or labels')
    if any(not isinstance(x,str) or not x.strip() for x in (*ranked,*grades)) or len(set(ranked))!=len(ranked):
        raise ValueError('invalid ranking identity')
    if any(type(g) is not int or not 0<=g<=3 for g in grades.values()):
        raise ValueError('reviewed integer grades required')
    ideal=dcg_at_k(sorted(grades.values(),reverse=True),k)
    actual=dcg_at_k([grades.get(x,0) for x in ranked],k)
    return actual/ideal if ideal else None

from math import fsum,isfinite
def mean_observed(values):
    if not isinstance(values,(list,tuple)) or len(values)>256:
        raise ValueError('bounded metric list required')
    numbers=[]
    for value in values:
        if value is None:
            continue
        if type(value) not in (bool,int,float):
            raise ValueError('numeric observation required')
        try:
            number=float(value)
        except (ValueError,OverflowError) as exc:
            raise ValueError('finite bounded metric required') from exc
        if not isfinite(number) or abs(number)>1000000:
            raise ValueError('finite bounded metric required')
        numbers.append(number)
    return fsum(numbers)/len(numbers) if numbers else None

def abstention_rate(cases):
    if not isinstance(cases,(list,tuple)) or len(cases)>64:
        raise ValueError('bounded cases required')
    if any(not isinstance(c,dict) or not {'answerable','has_evidence'}<=set(c) or type(c['answerable']) is not bool or type(c['has_evidence']) is not bool for c in cases):
        raise ValueError('boolean case observations required')
    subset=[c for c in cases if not c['answerable']]
    return sum(not c['has_evidence'] for c in subset)/len(subset) if subset else None

def citation_counts(validity):
    if not isinstance(validity,(list,tuple)) or len(validity)>128 or any(type(x) is not bool for x in validity):
        raise ValueError('bounded boolean validation results required')
    n=len(validity)
    valid=sum(validity)
    return dict(count=n,invalid=n-valid,valid_fraction=valid/n if n else None)

def context_metrics(selected, gold):
    if not isinstance(selected,(list,tuple)) or len(selected)>128 or not isinstance(gold,(set,frozenset)) or len(gold)>64:
        raise ValueError('bounded source units required')
    if any(not isinstance(key,tuple) or len(key)!=4 or any(not isinstance(v,str) or not v.strip() for v in key) for key in (*selected,*gold)):
        raise ValueError('fully scoped unit key required')
    units=set(selected)
    hits=len(units&gold)
    return dict(precision=hits/len(units) if units and gold else (0.0 if gold else None),recall=hits/len(gold) if gold else None)

