def support_complete(spans, expected):
    if not expected:
        return None
    return all(any(s['key']==key and normalize_answer(atom) in normalize_answer(s['quote']) for s in spans) for key,atoms in expected.items() for atom in atoms)

def audit_units(expected, raw, parsed, chunks):
    for key,atoms in expected.items():
        if key not in raw or any(atom not in raw[key] for atom in atoms):
            raise ValueError('oracle atom absent from declared raw source')
    total=sum(len(atoms) for atoms in expected.values())
    parsed_hits=sum(atom in parsed.get(key,'') for key,atoms in expected.items() for atom in atoms)
    complete=sum(all(any(c['key']==key and atom in c['text'] for c in chunks) for atom in atoms) for key,atoms in expected.items())
    return dict(parsed_atom_recall=parsed_hits/total if total else None,chunk_unit_recall=complete/len(expected) if expected else None)

def failure_flags(state):
    out=[]
    if state['answerable']:
        if state['candidate_recall']!=1:out.append('candidate_miss')
        if state['candidate_recall']==1 and state['ranked_recall']!=1:out.append('ranking_loss')
        if state['ranked_recall']==1 and not state['context_complete']:out.append('context_loss')
        if state['context_complete'] and state['answer_coverage']!=1:out.append('answer_atom_loss')
        if state['citation_count']==0:out.append('unexpected_abstention')
    elif state['citation_count']>0:
        out.append('unanswerable_evidence_returned')
    if state['invalid_count']>0:out.append('invalid_citation')
    if state['traceable'] is False:out.append('extractive_format_mismatch')
    return out

