        raise ValueError('bounded record list required')
    axes=('context_relevance','answer_faithfulness','answer_correctness','citation_support')
    return [dict(query_id=r['query_id'],run_id=r['run_id'],record_digest=r['record_digest'],rubric_version='procurement-review/1.0.0',status='pending',reviewer_kind=None,reviewer_id=None,judge_prompt_version=None,rationale=None,scores={axis:None for axis in axes}) for r in records]

def valid_review(review, expected):
    fields={'query_id','run_id','record_digest','rubric_version','status','reviewer_kind','reviewer_id','judge_prompt_version','scores','rationale'}
    axes={'context_relevance','answer_faithfulness','answer_correctness','citation_support'}
    if not isinstance(review,dict) or set(review)!=fields:
        raise ValueError('unexpected review fields')
    if any(review[k]!=expected[k] for k in ('query_id','run_id','record_digest')) or review['rubric_version']!='procurement-review/1.0.0':
        raise ValueError('stale review association')
    scores=review['scores']
    if not isinstance(scores,dict) or set(scores)!=axes:
        raise ValueError('all rubric axes required')
    if review['status']=='pending':
        if any(v is not None for v in scores.values()) or any(review[k] is not None for k in ('reviewer_kind','reviewer_id','judge_prompt_version','rationale')):
            raise ValueError('pending cannot claim a rating')
        return True
    def bounded(value,limit):
        return isinstance(value,str) and bool(value.strip()) and len(value)<=limit
    if review['status']!='reviewed' or review['reviewer_kind'] not in ('human','llm') or not bounded(review['reviewer_id'],200) or not bounded(review['rationale'],4000):
        raise ValueError('completed reviewer and rationale required')
    if any(type(v) is not int or not 1<=v<=5 for v in scores.values()):
        raise ValueError('integer ratings 1 to 5 required')
    if (review['reviewer_kind']=='human' and review['judge_prompt_version'] is not None) or (review['reviewer_kind']=='llm' and not bounded(review['judge_prompt_version'],200)):
        raise ValueError('invalid judge prompt identity')
    return True

def summarize_ratings(records, reviews):
    seen=set()
    queries=set()
    groups={}
    axes=('context_relevance','answer_faithfulness','answer_correctness','citation_support')
    for row in reviews:
        if row['status']=='pending':continue
        group=(row['reviewer_kind'],row['reviewer_id'],row['judge_prompt_version'])
        key=(row['query_id'],*group)
        if key in seen:raise ValueError('duplicate completed rating')
        seen.add(key)
        queries.add(row['query_id'])
        groups.setdefault(group,[]).append(row['scores'])
    return dict(reviewed_count=len(queries),pending_count=len(records)-len(queries),groups={g:dict(rating_count=len(rows),mean_scores={a:sum(s[a] for s in rows)/len(rows) for a in axes}) for g,rows in groups.items()})

def paired_changes(baseline, treatment):
    for rows in (baseline,treatment):
        if not isinstance(rows,(list,tuple)) or len(rows)>64:raise ValueError('bounded paired rows required')
        for row in rows:
            if not isinstance(row,dict) or set(row)!={'query_id','support_complete','exact_match'}:raise ValueError('unexpected paired fields')
            if not isinstance(row['query_id'],str) or not row['query_id'].strip() or len(row['query_id'])>64 or (row['support_complete'] is not None and type(row['support_complete']) is not bool) or type(row['exact_match']) is not bool:raise ValueError('invalid paired observations')
        if len({r['query_id'] for r in rows})!=len(rows):raise ValueError('duplicate query')
    by_id={r['query_id']:r for r in treatment}
    if set(by_id)!={r['query_id'] for r in baseline}:raise ValueError('changed case population')
    out=dict(lost_support=[],gained_support=[],exact_match_gains=[])
    for before in baseline:
        key=before['query_id'];after=by_id[key]
        if (before['support_complete'] is None)!=(after['support_complete'] is None):raise ValueError('changed label population')
        if before['support_complete'] is True and after['support_complete'] is False:out['lost_support'].append(key)
        if before['support_complete'] is False and after['support_complete'] is True:out['gained_support'].append(key)
        if before['exact_match'] is False and after['exact_match'] is True:out['exact_match_gains'].append(key)
    return out

def grouped_splits(rows):
    if not isinstance(rows,(list,tuple)) or len(rows)>256:raise ValueError('bounded planned rows required')
    result={}
    for row in rows:
        if not isinstance(row,dict) or set(row)!={'group','split'}:raise ValueError('unexpected split fields')
        group,split=row['group'],row['split']
        if not isinstance(group,str) or not group.strip() or len(group)>200 or split not in ('train','validation','test'):raise ValueError('invalid split label')
        if group in result and result[group]!=split:raise ValueError('related group leaked across splits')
        result[group]=split
    return result

import hashlib
import json
def case_digest(record):
    if not isinstance(record,dict):raise ValueError('record object required')
    value={k:v for k,v in record.items() if k!='record_digest'}
    payload=json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode('utf-8')
    return hashlib.sha256(payload).hexdigest()

