def run_identity(dataset, system, normalization):
    if not isinstance(dataset,dict) or set(dataset)!={'id','version','corpus_digest','cases_digest','source_checks_digest'} or not isinstance(system,dict) or set(system)!={'config','dense','reranker','python','implementation_digest'}:
        raise ValueError('complete dataset/system identity required')
    if not isinstance(normalization,str) or not normalization.strip() or len(normalization)>200:raise ValueError('normalization identity required')
    value=dict(dataset=dataset,system=system,normalization=normalization)
    payload=json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode('utf-8')
    return hashlib.sha256(payload).hexdigest()
